def marginal_probabilities(series, states=STATES):
    """R: marginal_probabilities() -- all n+1 empirical state frequencies (no trimming)."""
    series = np.asarray(series, dtype=float)
    T = series.size
    return np.array([np.sum(series == s) / T for s in np.asarray(states, dtype=float)])


def joint_probabilities(series, lag=1, states=STATES):
    """R: joint_probabilities() -- full (n+1) x (n+1) matrix of p_ij(lag) (no trimming)."""
    series = np.asarray(series, dtype=float)
    T = series.size
    states = np.asarray(states, dtype=float)
    n = len(states)
    a = series[lag:]
    b = series[0:T - lag]
    M = np.zeros((n, n))
    for i in range(n):
        for j in range(n):
            M[i, j] = float(np.mean((a == states[i]) & (b == states[j])))
    return M


def build_dataset_pmf(series_list, states=STATES, lags=(1, 2)):
    """dataset_2 of Section 4.3.2 (PMF based features, same cbind/unlist conventions)."""
    blocks = [np.vstack([marginal_probabilities(s, states) for s in series_list])]
    for lag in lags:
        blocks.append(np.vstack([joint_probabilities(s, lag=lag, states=states).ravel(order="F")
                                 for s in series_list]))
    return np.hstack(blocks)


def naive_c_marginal(series, states=STATES):
    """Independent loop-based re-implementation used as a sanity check of the port."""
    series = list(np.asarray(series, dtype=float))
    T = len(series)
    out = []
    for i in range(len(states) - 1):
        c = 0
        for t in range(T):
            if series[t] <= states[i]:
                c += 1
        out.append(c / T)
    return np.array(out)


def naive_c_joint(series, lag=1, states=STATES):
    """Independent loop-based reference for one cumulative joint matrix (last row/col dropped)."""
    series = list(np.asarray(series, dtype=float))
    T = len(series)
    n = len(states) - 1
    M = np.zeros((n, n))
    for i in range(n):
        for j in range(n):
            c = 0
            for t in range(lag, T):
                if series[t] <= states[i] and series[t - lag] <= states[j]:
                    c += 1
            M[i, j] = c / (T - lag)
    return M


